import React, { useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import { addUser } from "../../services/ApiUser"; // Adapte ce chemin si besoin

const CardAddAdmin = () => {
  const { agenceId } = useParams();
  const history = useHistory(); // Remplace useNavigate pour la v5
  const [formData, setFormData] = useState({
    username: "",
    email: "",
    password: "",
    age: "",
    user_image: null,
  });

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === "user_image") {
      setFormData({ ...formData, user_image: files[0] });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (formData.age && (parseInt(formData.age) < 18 || parseInt(formData.age) > 100)) {
      alert("L'âge doit être entre 18 et 100 ans.");
      return;
    }

    try {
      const data = new FormData();
      data.append("username", formData.username);
      data.append("email", formData.email);
      data.append("password", formData.password);
      data.append("age", formData.age);
      data.append("role", "admin");
      data.append("agence", agenceId);
      if (formData.user_image) {
        data.append("user_image", formData.user_image);
      }

      await addUser(data);
      alert("Admin ajouté avec succès !");
      history.push("/admin/Agence"); // Redirection avec useHistory
    } catch (error) {
      console.error(error);
      alert("Erreur lors de l'ajout.");
    }
  };

  return (
    <div className="max-w-md mx-auto bg-white p-6 rounded shadow">
      <h2 className="text-2xl font-bold mb-4">Ajouter un Administrateur</h2>
      <form onSubmit={handleSubmit} encType="multipart/form-data" className="space-y-4">
        <input
          type="text"
          name="username"
          placeholder="Nom d'utilisateur"
          value={formData.username}
          onChange={handleChange}
          required
          className="w-full border px-3 py-2 rounded"
        />
        <input
          type="email"
          name="email"
          placeholder="Adresse email"
          value={formData.email}
          onChange={handleChange}
          required
          className="w-full border px-3 py-2 rounded"
        />
        <input
          type="password"
          name="password"
          placeholder="Mot de passe"
          value={formData.password}
          onChange={handleChange}
          required
          className="w-full border px-3 py-2 rounded"
        />
        <input
          type="number"
          name="age"
          placeholder="Âge"
          value={formData.age}
          onChange={handleChange}
          className="w-full border px-3 py-2 rounded"
        />
        <input
          type="file"
          name="user_image"
          accept="image/*"
          onChange={handleChange}
          className="w-full"
        />
        <button
          type="submit"
          className="bg-blue-500 hover:bg-blue-700 text-white font-semibold px-4 py-2 rounded w-full"
        >
          Ajouter Admin
        </button>
      </form>
    </div>
  );
};

export default CardAddAdmin;
